_loaded = set()
def _load(key, ptx):
    if key not in _loaded:
        getattr(_mod, "load_" + key)(ptx)
        _loaded.add(key)

_CAP = torch.cuda.get_device_capability()
_BT = {}
def _bt_buffer(b):
    """A persistent (N K) buffer for b's transpose: a stable address keeps its TMA descriptor cached."""
    key = (b.shape[0], b.shape[1])
    bt = _BT.get(key)
    if bt is None:
        bt = torch.empty((b.shape[1], b.shape[0]), device=b.device, dtype=b.dtype)
        _BT[key] = bt
    return bt


def _transposed(b):
    """(K N) b -> a persistent (N K) contiguous copy, i.e. b in the col-major layout wgmma reads.
    Persistent so its address (and so its cached TMA descriptor) is stable across calls."""
    key = (b.shape[0], b.shape[1])
    bt = _BT.get(key)
    if bt is None:
        bt = torch.empty((b.shape[1], b.shape[0]), device=b.device, dtype=b.dtype)
        _BT[key] = bt
    bt.copy_(b.t())
    return bt


def custom_kernel(data: input_t) -> output_t:
    a, b, c = data
    M, K = a.shape
    N = b.shape[1]
    DIAG_CASES = [(4096, 5120, 4096, 123456), (2048, 3072, 2048, 32412)]

    for _k, _p in (("h100_2wg", PTX_H100_2WG), ("h100pk", PTX_H100PK), ("h100ne", PTX_H100NE),
                   ("transpose", PTX_TRANSPOSE)):
        _load(_k, _p)
    def DIAG_ARMS(a2, b2, c2):
        bt = _bt_buffer(b2)
        _mod.run_transpose(b2, b2, bt)
        torch.cuda.synchronize()
        def fresh(run):
            def f():
                c2.zero_()
                run(a2, bt, c2)
            return f
        return [
            ("kernel", lambda: _mod.run_h100_2wg(a2, bt, c2), False),
            ("pk", lambda: _mod.run_h100pk(a2, bt, c2), False),
            ("noepi", lambda: _mod.run_h100ne(a2, bt, c2), False),
            ("pk_chk", fresh(_mod.run_h100pk), True),
            ("torch", lambda: torch.matmul(a2, b2), False),
        ]

    import statistics
    from reference import generate_input, ref_kernel
    from utils import clear_l2_cache
    torch.backends.cuda.matmul.allow_tf32 = False
    rows = [f"device {torch.cuda.get_device_name(0)} cc{_CAP}"]
    for (m, n, k, seed) in DIAG_CASES:
        a2, b2, c2 = generate_input(m, n, k, seed)
        exp = ref_kernel((a2, b2, c2)).clone()
        def t(fn, reps=15):
            fn(); torch.cuda.synchronize()
            ts = []
            for _ in range(reps):
                clear_l2_cache()
                s = torch.cuda.Event(enable_timing=True); e = torch.cuda.Event(enable_timing=True)
                s.record(); fn(); e.record(); torch.cuda.synchronize()
                ts.append(s.elapsed_time(e) * 1000.0)
            return statistics.median(ts)
        out = [f"{m}x{n}x{k}:"]
        for name, fn, check in DIAG_ARMS(a2, b2, c2):
            us = t(fn)
            bad = ""
            if check:
                fn(); torch.cuda.synchronize()
                nbad = int(((c2.float() - exp.float()).abs() > 1e-5 * exp.float().abs()).sum().item())
                bad = f" bad={nbad}"
            out.append(f"{name}={us:.1f}us{bad}")
        rows.append(" ".join(out))
    raise RuntimeError("DIAG\n" + "\n".join(rows))

    return c
